for e in events:
 if int(e['recorded_at'])<=cutoff and (e['tube'] not in latest or int(e['recorded_at'])>int(latest[e['tube']]['recorded_at'])):
  latest[e['tube']]=e
times=[.25,.5,.75,1,1.25,2,3,4,5,6,8]
