import csv, json
from pathlib import Path
rows=list(csv.DictReader(open('observations.csv')))
acc=list(csv.DictReader(open('accession.csv')))
cut=12
states={r['tube']:'released' for r in rows}
for tube in states:
 ev=[e for e in acc if e['tube']==tube and int(e['release_on'])<=cut]
 if ev:
  ev.sort(key=lambda e:int(e['recorded_at']))
  states[tube]=ev[-1]['state']
areas={}
for subj in ('1','2'):
 rr=[r for r in rows if r['subject']==subj]
 rr.sort(key=lambda r:float(r['hours']))
 complete=all(states[r['tube']]=='released' for r in rr)
 areas[subj]=sum((float(b['hours'])-float(a['hours']))*(float(a['analyzer_value'])+float(b['analyzer_value']))/2 for a,b in zip(rr,rr[1:])) if complete else None
 print(subj, complete, areas[subj], [(r['tube'],states[r['tube']]) for r in rr if states[r['tube']]!='released'])
if areas['1'] is None or areas['2'] is None:
 result={'area_a':areas['1'],'area_b':areas['2'],'excess_pct':None,'conclusion':'defer'}
else:
 excess=100*(areas['2']/areas['1']-1)
 result={'area_a':round(areas['1'],4),'area_b':round(areas['2'],4),'excess_pct':round(excess,4),'conclusion':'above_margin' if excess>25 else 'within_margin'}
Path('answer.json').write_text(json.dumps(result,indent=2)+'\n')
print(Path('answer.json').read_text())

